using System.Collections.Generic;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "SeaRequiemAction", menuName = "Data/Battle/Battle Actions/Cellarius/SeaRequiem Action")]
public class SeaRequiemAction : BattleAction
{
	[Header("Sea Requiem")]
	[SerializeField]
	private PurifyAction purifyAction;

	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[SerializeField]
	private int seaRequiemIncreaseAmount;

	[SerializeField]
	private DefaultEffectAction seaRequiemEffectAction;

	public int SeaRequiemIncreaseAmount => seaRequiemIncreaseAmount;

	public override bool CheckConditionToBeCasted(int actionValue)
	{
		List<GameObject> activeCorruptedAnimals = currentCorruptedAnimals.activeCorruptedAnimals;
		bool result = false;
		for (int i = 0; i < activeCorruptedAnimals.Count; i++)
		{
			if (activeCorruptedAnimals[i].GetComponent<CorruptionStats>().CurrentCorruption <= (float)actionValue)
			{
				result = true;
			}
		}
		return result;
	}

	public override bool CheckCondition(GameObject target, int actionValue)
	{
		return target.GetComponent<CorruptionStats>().CurrentCorruption <= (float)actionValue;
	}

	public override void CastTargetAmount(GameObject corruptedAnimal, int purifyAmount, GameObject source)
	{
		purifyAction.CastTargetAmountPierce(corruptedAnimal, purifyAmount, source);
	}

	public void AddSeaRequiem(int seaRequiemAmount)
	{
		seaRequiemEffectAction.CastTargetAmountNoGameStateChange(ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject, seaRequiemIncreaseAmount * seaRequiemAmount, null);
	}
}
